head.script:

	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};

	scwin.test = function() {
		var z = gen_sbm.getChild(0, "udc_sbmMultiItem");
		var w = gen_sbm.getChild(0, "udc_sbmMultiItem2");
		console.log(z, w, z && w ? "success" : "fail");
		window.result = z && w ? "success" : "fail";
	}

	scwin.rolePopupObjMake = function(udc_multiItem) {
		var roleObjArr = [];
		var udcObj = udc_multiItem.getItemList();

		for(var i=0; i<udcObj.length; i++) {
			var idArr = udcObj[i].roleId.split(",");

			var roleObj = { roleId : idArr[0],
						    roleNm : udcObj[i].roleNm,
						    aplyStrtDttm : idArr[1],
						    aplyEndDttm : idArr[2],
						    roleCdNm : idArr[3],
						    useYn : idArr[4]};

			roleObjArr.push(roleObj);
		}

		return roleObjArr;
	};

	scwin.btn_actAdd_onclick = function(e) {

		gen_sbm.insertChild(gen_sbm.getChildrenCount());

        scwin.test();
	};

	scwin.btn_actPopup_onclick = function(e) {
		var roleObj = scwin.rolePopupObjMake(gen_sbm.getChild(this.getGeneratedIndex(), "udc_sbmMultiItem"));

		var data = {
			roleCd : "A",
			rolePgmRelCd : "A",
			genIdx : this.getGeneratedIndex(),
			role : roleObj,
			callbackFn : "scwin.actPopupCallBack"
		};

		//scwin.btn_roleSearch_popup(data);
	};

	scwin.Dbclick = function(id) {
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireDbClick(el);
	}
	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondblclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function') {
			node.ondblclick();
		}
	}	
	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('gen_sbm_0_wframe1').innerText == 'wframe';
	}
	scwin.checkVal2 = function() {
		return window.result == 'success';
	}	
	scwin.unitTest = function(){
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_actAdd').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
